import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    static int countPositiveConcurrently(int[] values) throws Exception {
        int midpoint = values.length / 2;
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<Integer> left = executor.submit(() -> countPositive(values, 0, midpoint));
            Future<Integer> right = executor.submit(() -> countPositive(values, midpoint, values.length));
            return left.get() + right.get();
        } finally {
            executor.shutdown();
        }
    }

    private static int countPositive(int[] values, int start, int end) {
        int count = 0;
        for (int index = start; index < end; index += 1) {
            if (values[index] > 0) {
                count += 1;
            }
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        System.out.println(countPositiveConcurrently(new int[] { 3, -1, 2, 7 }));
    }
}
